func apply(nodes []any, st step) []any {
	out := make([]any, 0, len(nodes))
	for _, n := range nodes {
		switch st.kind {
		case kindMember:
			if m, ok := n.(map[string]any); ok {
				if v, ok := m[st.name]; ok {
					out = append(out, v)
				}
			}
		case kindIndex:
			if a, ok := n.([]any); ok {
				i := st.index
				if i < 0 {
					i += len(a)
				}
				if i >= 0 && i < len(a) {
					out = append(out, a[i])
				}
			}
		case kindWildcard:
			switch v := n.(type) {
			case []any:
				out = append(out, v...)
			case map[string]any:
				keys := make([]string, 0, len(v))
				for k := range v { keys = append(keys, k) }
				sort.Strings(keys)
				for _, k := range keys { out = append(out, v[k]) }
			}
		case kindRecursive:
			out = append(out, recurse(n, st.name)...)
		}
	}
	return out
}

func recurse(n any, name string) []any {
	var out []any
	if m, ok := n.(map[string]any); ok {
		if v, ok := m[name]; ok {
			out = append(out, v)
		}
		keys := sorted keys
		for _, k := range keys {
			out = append(out, recurse(m[k], name)...)
